begin;

alter table public.lukas_drawing_canvases add column output_profile jsonb;
create function private.lukas_drawing_output_profile_valid(p jsonb,w numeric,h numeric)
returns boolean language plpgsql immutable set search_path='' as $$
declare paper_w double precision; paper_h double precision; scale double precision;
  actual_w double precision; actual_h double precision;
  expected_w double precision; expected_h double precision;
  tolerance_w double precision; tolerance_h double precision;
begin
  if p is null then return true; end if;
  if pg_catalog.jsonb_typeof(p)<>'object' or not(p ?& array['paper','orientation','widthMillimeters','heightMillimeters','scaleDenominator'])
    or p-array['paper','orientation','widthMillimeters','heightMillimeters','scaleDenominator']<>'{}'::jsonb
    or private.lukas_drawing_p2_name(p->'paper') is not true
    or pg_catalog.jsonb_typeof(p->'orientation') is distinct from 'string'
    or p->>'orientation' not in('landscape','portrait')
    or pg_catalog.jsonb_typeof(p->'widthMillimeters') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p->'heightMillimeters') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p->'scaleDenominator') is distinct from 'number' then return false; end if;
  paper_w:=(p->>'widthMillimeters')::double precision;
  paper_h:=(p->>'heightMillimeters')::double precision;
  scale:=(p->>'scaleDenominator')::double precision;
  actual_w:=w::double precision; actual_h:=h::double precision;
  if not coalesce(paper_w>0 and paper_w<=999999999999
    and paper_h>0 and paper_h<=999999999999
    and scale>0 and scale<=999999999999
    and actual_w>0 and actual_w<=999999999999
    and actual_h>0 and actual_h<=999999999999,false)
    or (p->>'orientation'='landscape' and paper_w<=paper_h)
    or (p->>'orientation'='portrait' and paper_h<=paper_w) then return false; end if;
  -- Profiled model dimensions must already lie on the numeric(18,6) storage grid.
  -- Compare exact JSON numerics, not rounded floats; legacy canvases bypass this.
  if pg_catalog.round(w,6)<>w or pg_catalog.round(h,6)<>h then return false; end if;
  -- Use the canonical IEEE754 product and eight-epsilon magnitude-relative test.
  -- PostgreSQL rejects product overflow/underflow; JavaScript rejects Infinity/zero.
  expected_w:=paper_w*scale; expected_h:=paper_h*scale;
  if expected_w<=0 or expected_h<=0 then return false; end if;
  begin
    tolerance_w:=2.220446049250313e-16::double precision*greatest(pg_catalog.abs(actual_w),pg_catalog.abs(expected_w))*8;
  exception when numeric_value_out_of_range then tolerance_w:=0; end;
  begin
    tolerance_h:=2.220446049250313e-16::double precision*greatest(pg_catalog.abs(actual_h),pg_catalog.abs(expected_h))*8;
  exception when numeric_value_out_of_range then tolerance_h:=0; end;
  return pg_catalog.abs(actual_w-expected_w)<=tolerance_w
    and pg_catalog.abs(actual_h-expected_h)<=tolerance_h;
exception when others then return false;
end;
$$;
alter table public.lukas_drawing_canvases add constraint lukas_drawing_canvas_output_profile_check
  check(private.lukas_drawing_output_profile_valid(output_profile,width_mm,height_mm) is true);

-- Preserve the established operation validators and legacy serialized bytes.
alter function private.lukas_drawing_structure_action_valid(jsonb,uuid) rename to lukas_drawing_structure_action_valid_pre_output_profile;
create function private.lukas_drawing_structure_action_valid(p_action jsonb,p_revision_id uuid)
returns boolean language plpgsql stable set search_path='' as $$
begin
  if p_action->>'kind'='put_canvas' and p_action->'entity' ? 'outputProfile' then
    if pg_catalog.jsonb_typeof(p_action->'entity'->'outputProfile') is distinct from 'object'
      or private.lukas_drawing_output_profile_valid(p_action->'entity'->'outputProfile',
        (p_action->'entity'->>'widthMillimeters')::numeric,(p_action->'entity'->>'heightMillimeters')::numeric) is not true then return false; end if;
    return private.lukas_drawing_structure_action_valid_pre_output_profile(
      pg_catalog.jsonb_set(p_action,'{entity}',(p_action->'entity')-'outputProfile'),p_revision_id);
  end if;
  return private.lukas_drawing_structure_action_valid_pre_output_profile(p_action,p_revision_id);
exception when others then return false;
end;
$$;
alter function private.lukas_drawing_structure_entity_json(text,uuid,uuid,uuid) rename to lukas_drawing_structure_entity_json_pre_output_profile;
create function private.lukas_drawing_structure_entity_json(p_kind text,p_id uuid,p_revision_id uuid,p_project_id uuid)
returns jsonb language plpgsql stable set search_path='' as $$
declare v jsonb; p jsonb;
begin
  v:=private.lukas_drawing_structure_entity_json_pre_output_profile(p_kind,p_id,p_revision_id,p_project_id);
  if p_kind='canvas' then
    select output_profile into p from public.lukas_drawing_canvases where id=p_id and revision_id=p_revision_id and project_id=p_project_id;
    if p is not null then v:=v||pg_catalog.jsonb_build_object('outputProfile',p); end if;
  end if;
  return v;
end;
$$;
alter function private.lukas_drawing_p2_canonical_snapshot(uuid,boolean) rename to lukas_drawing_p2_canonical_snapshot_pre_output_profile;
create function private.lukas_drawing_p2_canonical_snapshot(p_revision_id uuid,p_include_instance_lineage boolean)
returns jsonb language plpgsql stable set search_path='' as $$
declare v jsonb; canvases jsonb;
begin
  v:=private.lukas_drawing_p2_canonical_snapshot_pre_output_profile(p_revision_id,p_include_instance_lineage);
  select pg_catalog.jsonb_agg(x.value||case when c.output_profile is null then '{}'::jsonb else pg_catalog.jsonb_build_object('outputProfile',c.output_profile) end order by x.ordinality)
    into canvases from pg_catalog.jsonb_array_elements(v->'canvases') with ordinality x
    join public.lukas_drawing_canvases c on c.id=(x.value->>'id')::uuid and c.revision_id=p_revision_id;
  return pg_catalog.jsonb_set(v,'{canvases}',coalesce(canvases,'[]'::jsonb));
end;
$$;

create table private.lukas_drawing_native_assets (
  kind text not null check(kind in('workspace_template','block')),
  key text not null check(key~'^[a-z][a-z0-9-]{0,80}$'),
  version integer not null check(version>0),
  definition jsonb not null check(pg_catalog.jsonb_typeof(definition)='object'),
  content_sha256 text not null check(content_sha256=pg_catalog.encode(extensions.digest(definition::text,'sha256'),'hex')),
  artifact_sha256 text not null check(artifact_sha256~'^[0-9a-f]{64}$'),
  primary key(key,version),
  check(definition->>'key'=key and (definition->>'version')::integer=version)
);
