create trigger lukas_drawing_native_asset_immutable before update or delete on private.lukas_drawing_native_assets
for each row execute function private.lukas_drawing_platform_starter_guard();

alter table public.lukas_drawing_library_versions
  add column native_asset_key text,
  add column native_asset_version integer,
  drop constraint lukas_drawing_library_versions_source_kind_value_check,
  drop constraint lukas_drawing_library_versions_source_kind_check,
  add constraint lukas_drawing_library_versions_source_kind_value_check check(source_kind in('project_revision','platform_starter','platform_native')),
  add constraint lukas_drawing_library_versions_native_asset_fkey foreign key(native_asset_key,native_asset_version) references private.lukas_drawing_native_assets(key,version),
  add constraint lukas_drawing_library_versions_source_kind_check check(
    (source_kind='project_revision' and source_project_id is not null and source_revision_id is not null and platform_starter_key is null and platform_starter_version is null and native_asset_key is null and native_asset_version is null)
    or (source_kind='platform_starter' and source_project_id is null and source_revision_id is null and source_entity_id is null and platform_starter_key is not null and platform_starter_version is not null and native_asset_key is null and native_asset_version is null)
    or (source_kind='platform_native' and source_project_id is null and source_revision_id is null and source_entity_id is null and platform_starter_key is null and platform_starter_version is null and native_asset_key is not null and native_asset_version is not null)
  );
create unique index lukas_drawing_library_versions_native_asset_key on public.lukas_drawing_library_versions(organization_id,native_asset_key,native_asset_version) where source_kind='platform_native';

create function private.lukas_drawing_native_version_guard() returns trigger language plpgsql set search_path='' as $$
declare asset private.lukas_drawing_native_assets%rowtype;
begin
  if tg_op='UPDATE' and (old.source_kind='platform_native' or new.source_kind='platform_native') then
    if old.source_kind is distinct from new.source_kind or old.native_asset_key is distinct from new.native_asset_key
      or old.native_asset_version is distinct from new.native_asset_version or old.status<>'draft'
      or new.status<>'published' then raise exception using errcode='P1C01',message='Native catalog ancestry and lifecycle are immutable'; end if;
  end if;
  if new.source_kind='platform_native' then
    select * into asset from private.lukas_drawing_native_assets where key=new.native_asset_key and version=new.native_asset_version;
    if not found or new.canonical_payload is distinct from asset.definition or new.content_sha256 is distinct from asset.content_sha256
      or not exists(select 1 from public.lukas_drawing_library_entries where id=new.registry_id and kind=asset.kind)
    then raise exception using errcode='P1C01',message='Native catalog content must match authority'; end if;
  end if;
  return new;
end;
$$;
create trigger aaa_lukas_drawing_native_version_guard before insert or update on public.lukas_drawing_library_versions
for each row execute function private.lukas_drawing_native_version_guard();
-- Native publication is base drawing functionality. Existing company quotas remain unchanged.
alter function private.lukas_drawing_library_versions_entitlement_guard() rename to lukas_drawing_library_versions_entitlement_guard_pre_native;
create function private.lukas_drawing_library_versions_entitlement_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare v_entitlement public.lukas_qto_organization_entitlement_versions%rowtype;
begin
  if new.source_kind='platform_native' then return new; end if;
  if tg_op='UPDATE' and old.status='draft' and new.status='published' then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.organization_id::text,0));
    select * into v_entitlement from private.lukas_qto_current_entitlement(new.organization_id);
    if not private.lukas_qto_organization_library_access(new.organization_id) then raise exception using errcode='P7A07',message='Organization library entitlement is unavailable'; end if;
    if (select pg_catalog.count(*) from public.lukas_drawing_library_versions v where v.organization_id=new.organization_id and v.status in('published','deprecated') and v.source_kind<>'platform_native')>=v_entitlement.library_version_limit then raise exception using errcode='P7A07',message='Organization library version quota reached'; end if;
  end if;
  return new;
end;
$$;
drop trigger lukas_drawing_library_versions_entitlement_guard on public.lukas_drawing_library_versions;
create trigger lukas_drawing_library_versions_entitlement_guard before update on public.lukas_drawing_library_versions for each row execute function private.lukas_drawing_library_versions_entitlement_guard();

-- The staff entitlement change uses the same paid usage domain as publication.
do $quota$
declare source text; before_predicate text:=$match$v.organization_id=p_organization_id and v.status in('published','deprecated')$match$;
begin
  source:=pg_catalog.pg_get_functiondef('public.lukas_qto_set_organization_entitlement(uuid,text,integer,integer,integer,timestamptz,jsonb,text,uuid)'::regprocedure);
  if pg_catalog.strpos(source,before_predicate)=0 then raise exception 'Native quota predecessor mismatch'; end if;
  execute pg_catalog.replace(source,before_predicate,before_predicate||$replacement$ and v.source_kind<>'platform_native'$replacement$);
end;
$quota$;

create function public.lukas_drawing_list_native_assets(p_project_id uuid,p_kind text)
returns table(kind text,key text,version integer,name text,description text,definition jsonb,"contentSha256" text,"artifactSha256" text)
language plpgsql stable security definer set search_path='' as $$
begin
  if (select auth.uid()) is null or not private.lukas_qto_verified_session()
    or private.lukas_drawing_workspace_capability(p_project_id) is null
    or p_kind is null or p_kind not in('workspace_template','block')
    or not exists(select 1 from public.lukas_qto_projects p where p.id=p_project_id and private.lukas_qto_organization_role(p.organization_id) is not null)
  then raise exception using errcode='P1R01',message='Native drawing catalog is unavailable'; end if;
  return query select a.kind,a.key,a.version,a.definition->>'name',a.definition->>'description',a.definition,a.content_sha256,a.artifact_sha256
    from private.lukas_drawing_native_assets a where a.kind=p_kind order by a.key collate "C",a.version;
end;
$$;

-- NATIVE_CLONE_HELPER
create function private.lukas_drawing_catalog_rows(p_snapshot jsonb,p_kind text)
returns jsonb language sql immutable set search_path='' as $$
  select coalesce(pg_catalog.jsonb_agg(converted.value||case
    when p_kind='objects' then pg_catalog.jsonb_build_object('status','active','object_type',coalesce(item->'type',item->'geometry'->'type'),'page_id',coalesce(item->'pageId',(select c->'pageId' from pg_catalog.jsonb_array_elements(p_snapshot->'layers') l join pg_catalog.jsonb_array_elements(p_snapshot->'canvases') c on c->>'id'=l->>'canvasId' where l->>'id'=item->>'layerId')))
    when p_kind='layers' then pg_catalog.jsonb_build_object('page_id',coalesce(item->'pageId',(select c->'pageId' from pg_catalog.jsonb_array_elements(p_snapshot->'canvases') c where c->>'id'=item->>'canvasId')))
    when p_kind='pages' then pg_catalog.jsonb_build_object('width_mm',coalesce(item->'widthMillimeters',p_snapshot->'canvases'->0->'widthMillimeters','1000'::jsonb),'height_mm',coalesce(item->'heightMillimeters',p_snapshot->'canvases'->0->'heightMillimeters','1000'::jsonb)) else '{}'::jsonb end),'[]'::jsonb)
  from pg_catalog.jsonb_array_elements(p_snapshot->p_kind) item
  cross join lateral (select pg_catalog.jsonb_object_agg(case key
    when 'type' then 'object_type' when 'columns' then 'columns_json' when 'rows' then 'rows_json'
    when 'widthMillimeters' then 'width_mm' when 'heightMillimeters' then 'height_mm'
    else pg_catalog.lower(pg_catalog.regexp_replace(key,'([A-Z])','_\1','g')) end,value) value
    from pg_catalog.jsonb_each(item)) converted
$$;
create or replace function private.lukas_drawing_clone_catalog_graph(
  p_snapshot jsonb,p_target_project_id uuid,p_actor uuid,p_title text
) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_ids jsonb; v_document_id uuid; v_revision_id uuid;
  v_page_map jsonb:='{}'::jsonb; v_canvas_map jsonb:='{}'::jsonb;
  v_layer_map jsonb:='{}'::jsonb; v_style_map jsonb:='{}'::jsonb;
  v_block_map jsonb:='{}'::jsonb; v_instance_map jsonb:='{}'::jsonb;
  v_object_map jsonb:='{}'::jsonb; v_schema_map jsonb:='{}'::jsonb;
  v_column_map jsonb; v_row record; v_item jsonb; v_new_id uuid;
  v_json jsonb; v_columns jsonb; v_rows jsonb; v_cells jsonb;
begin
  if p_actor is null or p_actor is distinct from (select auth.uid())
    or coalesce(private.lukas_drawing_workspace_capability(p_target_project_id),'') not in('admin','editor') then
    raise exception using errcode='P1R01',message='Drawing graph target is unavailable';
  end if;
  -- Allocate every graph identity before writing any references, including embedded tables.
  select pg_catalog.jsonb_object_agg(id,extensions.gen_random_uuid()) into v_ids from (
    select entity->>'id' id from pg_catalog.jsonb_each(p_snapshot) collection
      cross join lateral pg_catalog.jsonb_array_elements(collection.value) entity
      where collection.key in('pages','canvases','layers','styles','blocks','objects','blockInstances','propertySchemas','propertyValues','tables')
    union select item->>'id' from pg_catalog.jsonb_array_elements(p_snapshot->'tables') t cross join lateral pg_catalog.jsonb_array_elements(t->'columns') item
    union select item->>'id' from pg_catalog.jsonb_array_elements(p_snapshot->'tables') t cross join lateral pg_catalog.jsonb_array_elements(t->'rows') item
  ) identities where id is not null;
  insert into public.lukas_drawing_documents(project_id,title,created_by)
  values(p_target_project_id,p_title,p_actor) returning id into v_document_id;
  insert into public.lukas_drawing_revisions(document_id,project_id,sequence,status,version,created_by)
  values(v_document_id,p_target_project_id,1,'draft',1,p_actor) returning id into v_revision_id;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_pages,private.lukas_drawing_catalog_rows(p_snapshot,'pages')) order by sort_order,id loop
    v_new_id:=(v_ids->>v_row.id::text)::uuid; v_page_map:=v_page_map||pg_catalog.jsonb_build_object(v_row.id::text,v_new_id);
    insert into public.lukas_drawing_pages(id,revision_id,project_id,name,page_number,sort_order,version,width_mm,height_mm)
    values(v_new_id,v_revision_id,p_target_project_id,v_row.name,v_row.sort_order+1,v_row.sort_order,1,v_row.width_mm,v_row.height_mm);
  end loop;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_canvases,private.lukas_drawing_catalog_rows(p_snapshot,'canvases')) order by sort_order,id loop
    v_new_id:=(v_ids->>v_row.id::text)::uuid; v_canvas_map:=v_canvas_map||pg_catalog.jsonb_build_object(v_row.id::text,v_new_id);
    insert into public.lukas_drawing_canvases(id,page_id,revision_id,project_id,name,space_kind,width_mm,height_mm,sort_order,version,created_by,output_profile)
    values(v_new_id,(v_page_map->>v_row.page_id::text)::uuid,v_revision_id,p_target_project_id,v_row.name,v_row.space_kind,v_row.width_mm,v_row.height_mm,v_row.sort_order,1,p_actor,v_row.output_profile);
  end loop;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_layers,private.lukas_drawing_catalog_rows(p_snapshot,'layers')) order by sort_order,id loop
    v_new_id:=(v_ids->>v_row.id::text)::uuid; v_layer_map:=v_layer_map||pg_catalog.jsonb_build_object(v_row.id::text,v_new_id);
    insert into public.lukas_drawing_layers(id,page_id,canvas_id,revision_id,project_id,name,sort_order,visible,locked,system_kind,version,created_by)
    values(v_new_id,(v_page_map->>v_row.page_id::text)::uuid,(v_canvas_map->>v_row.canvas_id::text)::uuid,v_revision_id,p_target_project_id,v_row.name,v_row.sort_order,v_row.visible,
      case when v_row.system_kind='source' then true else false end,
      v_row.system_kind,1,p_actor);
  end loop;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_styles,private.lukas_drawing_catalog_rows(p_snapshot,'styles')) order by id loop
    v_new_id:=(v_ids->>v_row.id::text)::uuid; v_style_map:=v_style_map||pg_catalog.jsonb_build_object(v_row.id::text,v_new_id);
    insert into public.lukas_drawing_styles(id,revision_id,project_id,name,value,version,created_by)
    values(v_new_id,v_revision_id,p_target_project_id,v_row.name,v_row.value,1,p_actor);
  end loop;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_blocks,private.lukas_drawing_catalog_rows(p_snapshot,'blocks')) order by id loop
    v_new_id:=(v_ids->>v_row.id::text)::uuid; v_block_map:=v_block_map||pg_catalog.jsonb_build_object(v_row.id::text,v_new_id);
    select pg_catalog.jsonb_agg(case when pg_catalog.jsonb_typeof(p->'styleId')='string'
      then pg_catalog.jsonb_set(p,'{styleId}',pg_catalog.to_jsonb((v_style_map->>(p->>'styleId'))::uuid)) else p end order by ord)
      into v_json from pg_catalog.jsonb_array_elements(v_row.primitives) with ordinality x(p,ord);
    insert into public.lukas_drawing_blocks(id,revision_id,project_id,name,primitives,version,created_by)
    values(v_new_id,v_revision_id,p_target_project_id,v_row.name,v_json,1,p_actor);
  end loop;
  for v_row in select id from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_objects,private.lukas_drawing_catalog_rows(p_snapshot,'objects')) where status='active' order by id loop
    v_object_map:=v_object_map||pg_catalog.jsonb_build_object(
      v_row.id::text,(v_ids->>v_row.id::text)::uuid
    );
  end loop;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_objects,private.lukas_drawing_catalog_rows(p_snapshot,'objects')) where status='active' order by id loop
    v_new_id:=(v_object_map->>v_row.id::text)::uuid;
    insert into public.lukas_drawing_objects(id,lineage_id,page_id,layer_id,revision_id,project_id,name,object_type,geometry,style_id,style,status,version,created_by,updated_by)
    values(v_new_id,v_new_id,(v_page_map->>v_row.page_id::text)::uuid,(v_layer_map->>v_row.layer_id::text)::uuid,v_revision_id,p_target_project_id,v_row.name,v_row.object_type,
      case when v_row.object_type='opening' then pg_catalog.jsonb_set(
        v_row.geometry,'{hostWallId}',pg_catalog.to_jsonb(
          (v_object_map->>(v_row.geometry->>'hostWallId'))::uuid
        )
      ) else v_row.geometry end,
      case when v_row.style_id is null then null else (v_style_map->>v_row.style_id::text)::uuid end,v_row.style,'active',1,p_actor,p_actor);
  end loop;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_block_instances,private.lukas_drawing_catalog_rows(p_snapshot,'blockInstances')) order by id loop
    v_new_id:=(v_ids->>v_row.id::text)::uuid; v_instance_map:=v_instance_map||pg_catalog.jsonb_build_object(v_row.id::text,v_new_id);
    insert into public.lukas_drawing_block_instances(id,lineage_id,block_id,layer_id,revision_id,project_id,name,origin,rotation,scale_x,scale_y,version,created_by)
    values(v_new_id,v_new_id,(v_block_map->>v_row.block_id::text)::uuid,(v_layer_map->>v_row.layer_id::text)::uuid,v_revision_id,p_target_project_id,v_row.name,v_row.origin,v_row.rotation,v_row.scale_x,v_row.scale_y,1,p_actor);
  end loop;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_property_schemas,private.lukas_drawing_catalog_rows(p_snapshot,'propertySchemas')) order by id loop
    v_new_id:=(v_ids->>v_row.id::text)::uuid; v_schema_map:=v_schema_map||pg_catalog.jsonb_build_object(v_row.id::text,v_new_id);
    insert into public.lukas_drawing_property_schemas(id,revision_id,project_id,name,value_type,enum_options,applies_to,required,version,created_by)
    values(v_new_id,v_revision_id,p_target_project_id,v_row.name,v_row.value_type,v_row.enum_options,v_row.applies_to,v_row.required,1,p_actor);
  end loop;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_property_values,private.lukas_drawing_catalog_rows(p_snapshot,'propertyValues')) order by id loop
    insert into public.lukas_drawing_property_values(id,schema_id,object_id,block_instance_id,revision_id,project_id,value,version,created_by)
    values((v_ids->>v_row.id::text)::uuid,(v_schema_map->>v_row.schema_id::text)::uuid,
      case when v_row.object_id is null then null else (v_object_map->>v_row.object_id::text)::uuid end,
      case when v_row.block_instance_id is null then null else (v_instance_map->>v_row.block_instance_id::text)::uuid end,
      v_revision_id,p_target_project_id,coalesce(v_row.value,'null'::jsonb),1,p_actor);
  end loop;
  for v_row in select * from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_tables,private.lukas_drawing_catalog_rows(p_snapshot,'tables')) order by id loop
    v_column_map:='{}'::jsonb; v_columns:='[]'::jsonb; v_rows:='[]'::jsonb;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_row.columns_json) loop
      v_new_id:=(v_ids->>(v_item->>'id'))::uuid; v_column_map:=v_column_map||pg_catalog.jsonb_build_object(v_item->>'id',v_new_id);
      v_item:=pg_catalog.jsonb_set(v_item,'{id}',pg_catalog.to_jsonb(v_new_id));
      if v_item->>'kind'='property' then v_item:=pg_catalog.jsonb_set(v_item,'{propertySchemaId}',pg_catalog.to_jsonb((v_schema_map->>(v_item->>'propertySchemaId'))::uuid)); end if;
      v_columns:=v_columns||pg_catalog.jsonb_build_array(v_item);
    end loop;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_row.rows_json) loop
      select coalesce(pg_catalog.jsonb_object_agg(v_column_map->>cell.key,cell.value),'{}'::jsonb) into v_cells from pg_catalog.jsonb_each(v_item->'cells') cell;
      v_item:=pg_catalog.jsonb_set(v_item,'{id}',pg_catalog.to_jsonb((v_ids->>(v_item->>'id'))::uuid));
      v_item:=pg_catalog.jsonb_set(v_item,'{cells}',v_cells);
      if v_item->>'objectId' is not null then v_item:=pg_catalog.jsonb_set(v_item,'{objectId}',pg_catalog.to_jsonb((v_object_map->>(v_item->>'objectId'))::uuid)); end if;
      if v_item->>'blockInstanceId' is not null then v_item:=pg_catalog.jsonb_set(v_item,'{blockInstanceId}',pg_catalog.to_jsonb((v_instance_map->>(v_item->>'blockInstanceId'))::uuid)); end if;
      v_rows:=v_rows||pg_catalog.jsonb_build_array(v_item);
    end loop;
    insert into public.lukas_drawing_tables(id,revision_id,project_id,name,columns_json,rows_json,version,created_by)
    values((v_ids->>v_row.id::text)::uuid,v_revision_id,p_target_project_id,v_row.name,v_columns,v_rows,1,p_actor);
  end loop;
  update public.lukas_drawing_layers target set locked=true,version=target.version+1
  from pg_catalog.jsonb_populate_recordset(null::public.lukas_drawing_layers,private.lukas_drawing_catalog_rows(p_snapshot,'layers')) source
  where source.system_kind<>'source'
    and source.locked and target.id=(v_layer_map->>source.id::text)::uuid
    and target.revision_id=v_revision_id and target.project_id=p_target_project_id;
  perform private.lukas_drawing_p4_assert_semantic_graph(v_revision_id);
  return pg_catalog.jsonb_build_object('documentId',v_document_id,'revisionId',v_revision_id);
end;
$$;

create or replace function private.lukas_drawing_clone_library_template(p_source_revision_id uuid,p_target_project_id uuid,p_actor uuid,p_title text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare snapshot jsonb;
begin
  snapshot:=private.lukas_drawing_p2_canonical_snapshot(p_source_revision_id,true);
  snapshot:=pg_catalog.jsonb_set(snapshot,'{pages}',(select pg_catalog.jsonb_agg(x.value||pg_catalog.jsonb_build_object('widthMillimeters',p.width_mm,'heightMillimeters',p.height_mm) order by x.ordinality) from pg_catalog.jsonb_array_elements(snapshot->'pages') with ordinality x join public.lukas_drawing_pages p on p.id=(x.value->>'id')::uuid));
  return private.lukas_drawing_clone_catalog_graph(snapshot,p_target_project_id,p_actor,p_title);
end;
$$;
revoke all on function private.lukas_drawing_catalog_rows(jsonb,text),private.lukas_drawing_clone_catalog_graph(jsonb,uuid,uuid,text),private.lukas_drawing_clone_library_template(uuid,uuid,uuid,text) from public,anon,authenticated,service_role;
-- END_NATIVE_CLONE_HELPER

create function public.lukas_drawing_import_native_asset(p_project_id uuid,p_revision_id uuid,p_kind text,p_asset_key text,p_asset_version integer,p_client_request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); org uuid; asset private.lukas_drawing_native_assets%rowtype;
  source public.lukas_drawing_library_versions%rowtype; entry_id uuid; existing public.lukas_drawing_library_imports%rowtype;
  request_sha text; result jsonb; target uuid; receipt uuid; snapshot jsonb; pair record; block_name text; suffix integer:=1;
begin
  if actor is null or p_client_request_id is null or not private.lukas_qto_verified_session()
    or coalesce(private.lukas_drawing_workspace_capability(p_project_id),'') not in('admin','editor')
    or p_kind is null or p_kind not in('workspace_template','block')
    or (p_kind='workspace_template' and p_revision_id is not null)
    or (p_kind='block' and p_revision_id is null)
  then raise exception using errcode='P1R01',message='Native drawing import is unavailable'; end if;
  select organization_id into org from public.lukas_qto_projects where id=p_project_id and private.lukas_qto_organization_role(organization_id) is not null;
  if org is null then raise exception using errcode='P1R01',message='Native drawing project is unavailable'; end if;
  select * into asset from private.lukas_drawing_native_assets where kind=p_kind and key=p_asset_key and version=p_asset_version;
  if not found then raise exception using errcode='P1R01',message='Native drawing asset is unavailable'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text||':'||p_client_request_id::text,0));
  request_sha:=pg_catalog.encode(extensions.digest(pg_catalog.jsonb_build_object('nativeKind',p_kind,'assetKey',p_asset_key,'assetVersion',p_asset_version,'projectId',p_project_id,'revisionId',p_revision_id)::text,'sha256'),'hex');
  select * into existing from public.lukas_drawing_library_imports where imported_by=actor and client_request_id=p_client_request_id;
  if found then
    if existing.request_sha256 is distinct from request_sha then raise exception using errcode='P1C01',message='Request ID does not match stored native import'; end if;
    return pg_catalog.jsonb_build_object('importId',existing.id,'revisionId',existing.target_revision_id,'contentSha256',existing.source_content_sha256)
      ||case when p_kind='block' then pg_catalog.jsonb_build_object('targetEntityId',existing.target_entity_id) else pg_catalog.jsonb_build_object('documentId',existing.target_document_id) end;
  end if;
  -- Matching receipts are read-only retries, even after a revision leaves draft.
  if p_kind='block' then
    perform 1 from public.lukas_drawing_revisions where id=p_revision_id and project_id=p_project_id and status='draft' for update;
    if not found then raise exception using errcode='P1R01',message='Native symbol requires an editable draft'; end if;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(org::text||':native:'||p_asset_key||':'||p_asset_version::text,0));
  select * into source from public.lukas_drawing_library_versions where organization_id=org and source_kind='platform_native' and native_asset_key=p_asset_key and native_asset_version=p_asset_version;
  if not found then
    insert into public.lukas_drawing_library_entries(organization_id,kind,name,created_by)
    values(org,p_kind,asset.definition->>'name',actor) returning id into entry_id;
    insert into public.lukas_drawing_library_versions(registry_id,organization_id,version_no,status,canonical_payload,content_sha256,source_kind,native_asset_key,native_asset_version,created_by)
    values(entry_id,org,1,'draft',asset.definition,asset.content_sha256,'platform_native',p_asset_key,p_asset_version,actor) returning * into source;
    update public.lukas_drawing_library_versions set status='published',published_by=actor,published_at=pg_catalog.now() where id=source.id returning * into source;
  end if;
  if p_kind='workspace_template' then
    snapshot:='{}'::jsonb;
    for pair in select * from pg_catalog.jsonb_each(asset.definition->'structure') where key<>'revisionId' loop
      snapshot:=snapshot||pg_catalog.jsonb_build_object(pair.key,(select coalesce(pg_catalog.jsonb_agg(value),'[]'::jsonb) from pg_catalog.jsonb_each(pair.value)));
    end loop;
    snapshot:=pg_catalog.jsonb_set(snapshot,'{canvases}',(select pg_catalog.jsonb_agg(value||pg_catalog.jsonb_build_object('outputProfile',asset.definition->'outputProfile')) from pg_catalog.jsonb_array_elements(snapshot->'canvases')));
    result:=private.lukas_drawing_clone_catalog_graph(snapshot,p_project_id,actor,asset.definition->>'name');
  else
    target:=extensions.gen_random_uuid();
    block_name:=asset.definition->>'name';
    while exists(select 1 from public.lukas_drawing_blocks where revision_id=p_revision_id and name=block_name) loop
      suffix:=suffix+1; block_name:=(asset.definition->>'name')||' ('||suffix::text||')';
    end loop;
    perform private.lukas_drawing_apply_operation(p_revision_id,extensions.gen_random_uuid(),'mutate_structure','{}'::jsonb,
      pg_catalog.jsonb_build_object('type','mutate_structure','actions',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'kind','put_block','baseVersion',null,'entity',pg_catalog.jsonb_build_object('id',target,'revisionId',p_revision_id,'name',block_name,'primitives',asset.definition->'primitives','version',1)))),
      pg_catalog.jsonb_build_object('type','mutate_structure','actions',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','delete_block','id',target,'baseVersion',1))),
      null,null);
    result:=pg_catalog.jsonb_build_object('targetEntityId',target,'revisionId',p_revision_id);
  end if;
  insert into public.lukas_drawing_library_imports(organization_id,registry_id,version_id,project_id,revision_id,target_entity_id,target_document_id,target_revision_id,source_content_sha256,imported_by,client_request_id,request_sha256)
  values(org,source.registry_id,source.id,p_project_id,p_revision_id,target,(result->>'documentId')::uuid,(result->>'revisionId')::uuid,asset.content_sha256,actor,p_client_request_id,request_sha) returning id into receipt;
  return result||pg_catalog.jsonb_build_object('importId',receipt,'contentSha256',asset.content_sha256);
end;
$$;

revoke all on function public.lukas_drawing_list_native_assets(uuid,text), public.lukas_drawing_import_native_asset(uuid,uuid,text,text,integer,uuid) from public,anon,authenticated,service_role;
grant execute on function public.lukas_drawing_list_native_assets(uuid,text), public.lukas_drawing_import_native_asset(uuid,uuid,text,text,integer,uuid) to authenticated;
revoke all on function private.lukas_drawing_native_version_guard(),private.lukas_drawing_library_versions_entitlement_guard(),private.lukas_drawing_library_versions_entitlement_guard_pre_native() from public,anon,authenticated,service_role;
-- PROFILE_MATERIALIZERS
do $profile$
declare proc record; source text; changed text; canvas_start integer; canvas_end integer; section text;
begin
  for proc in select pg_catalog.unnest(array[
    'private.lukas_drawing_apply_operation_pre_p2_contract_hardening(uuid,uuid,text,jsonb,jsonb,jsonb)'::regprocedure,
    'private.lukas_drawing_checkpoint_stage_canvases(uuid,jsonb,jsonb)'::regprocedure,
    'private.lukas_drawing_create_from_template_pre_p2_contract_hardening(uuid,text,uuid)'::regprocedure
  ])::oid oid loop
    source:=pg_catalog.pg_get_functiondef(proc.oid); changed:=source;
    if pg_catalog.strpos(source,'insert into public.lukas_drawing_canvases')=0 then raise exception 'Canvas materializer predecessor missing: %',proc.oid::regprocedure; end if;
    canvas_start:=pg_catalog.strpos(source,'insert into public.lukas_drawing_canvases');
    canvas_end:=pg_catalog.strpos(pg_catalog.substr(source,canvas_start),';')+canvas_start;
    section:=pg_catalog.substr(source,canvas_start,canvas_end-canvas_start);
    if pg_catalog.strpos(section,'output_profile')>0 then raise exception 'Canvas materializer predecessor already changed: %',proc.oid::regprocedure; end if;
    if pg_catalog.strpos(section,'v_entity')>0 then
      changed:=pg_catalog.replace(changed,section,pg_catalog.regexp_replace(section,'created_by([[:space:]]*)\)','created_by,output_profile\1)'));
      canvas_end:=pg_catalog.strpos(pg_catalog.substr(changed,canvas_start),';')+canvas_start;
      section:=pg_catalog.substr(changed,canvas_start,canvas_end-canvas_start);
      changed:=pg_catalog.replace(changed,section,pg_catalog.regexp_replace(section,'v_actor([[:space:]]*)\);$','v_actor,v_entity->''outputProfile''\1);'));
      changed:=pg_catalog.replace(changed,'else update public.lukas_drawing_canvases set name=v_entity->>''name'',','else update public.lukas_drawing_canvases set output_profile=v_entity->''outputProfile'',name=v_entity->>''name'',');
    elsif pg_catalog.strpos(section,'v_row.width_mm')>0 then
      changed:=pg_catalog.replace(changed,section,pg_catalog.regexp_replace(pg_catalog.regexp_replace(section,'created_by([[:space:]]*)\)','created_by,output_profile\1)'),'v_actor([[:space:]]*)\);$','v_actor,v_row.output_profile\1);'));
    end if;
    if changed=source or pg_catalog.strpos(changed,'output_profile')=0 then raise exception 'Canvas materializer profile patch failed: %',proc.oid::regprocedure; end if;
    execute changed;
  end loop;
end;
$profile$;
revoke all on function private.lukas_drawing_output_profile_valid(jsonb,numeric,numeric),private.lukas_drawing_structure_action_valid(jsonb,uuid),private.lukas_drawing_structure_action_valid_pre_output_profile(jsonb,uuid),private.lukas_drawing_structure_entity_json(text,uuid,uuid,uuid),private.lukas_drawing_structure_entity_json_pre_output_profile(text,uuid,uuid,uuid),private.lukas_drawing_p2_canonical_snapshot(uuid,boolean),private.lukas_drawing_p2_canonical_snapshot_pre_output_profile(uuid,boolean) from public,anon,authenticated,service_role;
-- END_PROFILE_MATERIALIZERS
commit;
